interface InvoiceResultsProps {
  data: InvoiceData
  onSave?: (data: InvoiceData) => void
}

export function InvoiceResults({ data, onSave }: InvoiceResultsProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editedData, setEditedData] = useState<InvoiceData>(data)

  const handleSave = () => {
    if (onSave) {
      onSave(editedData)
    }
    setIsEditing(false)
  }

  const updateLineItem = (index: number, field: string, value: string) => {
    const newItems = [...editedData.lineItems]
    newItems[index] = { ...newItems[index], [field]: value }
    setEditedData({ ...editedData, lineItems: newItems })
  }

  const updateField = (field: keyof InvoiceData, value: string) => {
    setEditedData({ ...editedData, [field]: value })
  }

  return (
    <div className="bg-white rounded-lg shadow-md p-6 space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Extracted Invoice Data</h2>
        <div className="flex gap-2">
          {isEditing ? (
            <>
              <Button onClick={handleSave} className="flex items-center gap-2">
                <Save className="w-4 h-4" /> Save
              </Button>
              <Button onClick={() => setIsEditing(false)} variant="outline">
                Cancel
              </Button>
            </>
          ) : (
            <Button onClick={() => setIsEditing(true)} className="flex items-center gap-2">
              <Edit className="w-4 h-4" /> Edit
            </Button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Invoice Number</label>
          {isEditing ? (
            <Input
              value={editedData.invoiceNumber}
              onChange={(e) => updateField('invoiceNumber', e.target.value)}
            />
          ) : (
            <p className="text-gray-900">{editedData.invoiceNumber}</p>
          )}
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
          {isEditing ? (
            <Input
              value={editedData.date}
              onChange={(e) => updateField('date', e.target.value)}
            />
          ) : (
            <p className="text-gray-900">{editedData.date}</p>
          )}
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Vendor</label>
          {isEditing ? (
            <Input
              value={editedData.vendor}
              onChange={(e) => updateField('vendor', e.target.value)}
            />
          ) : (
            <p className="text-gray-900">{editedData.vendor}</p>
          )}
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Total Amount</label>
          {isEditing ? (
            <Input
              value={editedData.totalAmount}
              onChange={(e) => updateField('totalAmount', e.target.value)}
            />
          ) : (
            <p className="text-gray-900 font-semibold">{editedData.totalAmount}</p>
          )}
        </div>
      </div>

      <div>
        <h3 className="text-lg font-semibold text-gray-800 mb-3">Line Items</h3>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Description</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Quantity</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Unit Price</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Amount</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {editedData.lineItems.map((item, index) => (
                <tr key={index}>
                  <td className="px-4 py-3">
                    {isEditing ? (
                      <Input
                        value={item.description}
                        onChange={(e) => updateLineItem(index, 'description', e.target.value)}
                      />
                    ) : (
                      <span className="text-gray-900">{item.description}</span>
                    )}
                  </td>
                  <td className="px-4 py-3">
                    {isEditing ? (
                      <Input
                        value={item.quantity}
                        onChange={(e) => updateLineItem(index, 'quantity', e.target.value)}
                        className="w-20"
                      />
                    ) : (
                      <span className="text-gray-900">{item.quantity}</span>
                    )}
                  </td>
                  <td className="px-4 py-3">
                    {isEditing ? (
                      <Input
                        value={item.unitPrice}
                        onChange={(e) => updateLineItem(index, 'unitPrice', e.target.value)}
                        className="w-24"
                      />
                    ) : (
                      <span className="text-gray-900">{item.unitPrice}</span>
                    )}
                  </td>
                  <td className="px-4 py-3">
