import Anthropic from '@anthropic-ai/sdk'
import { InvoiceData } from './types'
import { invoiceSchema } from './schemas'

const anthropic = new Anthropic({
  apiKey: process.env.ANTHROPIC_API_KEY || '',
})

export async function processPDFWithClaude(pdfBase64: string): Promise<InvoiceData> {
  const message = await anthropic.messages.create({
    model: 'claude-3-5-sonnet-20241022',
    max_tokens: 4096,
    messages: [
      {
        role: 'user',
        content: [
          {
            type: 'document',
            source: {
              type: 'base64',
              media_type: 'application/pdf',
              data: pdfBase64,
            },
          },
          {
            type: 'text',
            text: `Extract all invoice data from this PDF document. Return the data as a JSON object with the following structure:
{
  "invoiceNumber": "string",
  "date": "string",
  "vendor": "string",
  "totalAmount": "string",
  "currency": "string (optional)",
  "dueDate": "string (optional)",
  "taxAmount": "string (optional)",
  "subtotal": "string (optional)",
  "lineItems": [
    {
      "description": "string",
      "quantity": "string",
      "unitPrice": "string",
      "amount": "string"
    }
  ]
}

Extract all line items with their descriptions, quantities, unit prices, and amounts. Return ONLY valid JSON, no additional text.`,
          },
        ],
      },
    ],
  })

  const textContent = message.content.find((block) => block.type === 'text')
  if (!textContent || textContent.type !== 'text') {
    throw new Error('No text content in Claude response')
  }

  return extractInvoiceData(textContent.text)
}

export function extractInvoiceData(responseText: string): InvoiceData {
  let jsonText = responseText.trim()

  const jsonMatch = jsonText.match(/\{[\s\S]*\}/)
  if (jsonMatch) {
    jsonText = jsonMatch[0]
  }

  const parsedData = JSON.parse(jsonText)

  const validatedData = invoiceSchema.parse(parsedData)

  return validatedData
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function formatCurrency(amount: number, currency: string = 'USD'): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency,
  }).format(amount)
}

export function formatDate(date: Date | string, locale: string = 'en-US'): string {
  const dateObj = typeof date === 'string' ? new Date(date) : date
  return new Intl.DateTimeFormat(locale, {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  }).format(dateObj)
}

export function validateFileUpload(file: File, maxSize: number, allowedTypes: string[]): { valid: boolean; error?: string } {
  if (file.size > maxSize) {
    return { valid: false, error: `File size exceeds ${maxSize / 1024 / 1024}MB limit` }
  }
  if (!allowedTypes.includes(file.type)) {
    return { valid: false, error: `File type ${file.type} is not allowed` }
  }
  return { valid: true }
}

export async function pdfToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => {
      const base64String = reader.result as string
      const base64Data = base64String.split(',')[1]
      resolve(base64Data)
    }
    reader.onerror = (error) => reject(error)
    reader.readAsDataURL(file)
  })
}
